theorem betaAverage_congr_Ioo (a : ℝ) {f g : ℝ → ℝ}
    (hfg : ∀ x ∈ Ioo (0 : ℝ) 1, f x = g x) :
    betaAverage a f = betaAverage a g

theorem nestedKernel_hasSum (k : ℕ) (hk : k ≤ 5) {r : ℝ}
    (hr0 : 0 ≤ r) (hr1 : r < 1) :
    HasSum (fun n : ℕ => weight n * r ^ n * momentPrefix k n) (nestedKernel k r)

theorem hadamardEulerIntegral_eq_squaredNativeEuler (k : ℕ) {lambda r : ℝ}
    (hlambda : 0 < lambda) (hlr : lambda < r) (hr1 : r < 1) :
    hadamardEulerIntegral k lambda r = squaredNativeEuler k (lambda : ℂ)

private theorem beta_integrand_cast (u v x : ℝ) (hx : 0 ≤ x) (hx1 : x ≤ 1) :
    ((x ^ (u - 1) * (1 - x) ^ (v - 1) : ℝ) : ℂ) =
      (x : ℂ) ^ ((u : ℂ) - 1) * (1 - (x : ℂ)) ^ ((v : ℂ) - 1)

private theorem beta_moment_integrand {a x : ℝ} (n : ℕ) (hx : 0 < x) :
    x ^ (a + (n : ℝ) - 1) * (1 - x) ^ ((1 - a) - 1) =
      x ^ n * betaKernel a x

private theorem gaussDerivative_coefficient (n : ℕ) :
    (1 / 6 : ℝ) * gammaMoment (7 / 6) n * gammaMoment (5 / 6) (n + 1) =
      gaussCoefficient (n + 1) * ((n : ℝ) + 1)

theorem angular_circle_domain {lambda s : ℂ} {r : ℝ}
